(function(){
const $id=id=>document.getElementById(id);
const meals={
 'tr.yazir':'Elmalılı Hamdi Yazır',
 'tr.ates':'Süleyman Ateş',
 'tr.bulac':'Ali Bulaç',
 'tr.yildirim':'Suat Yıldırım'
};
let changing=false;
function validateMeal(data,id){if(data?.edition?.identifier!==id||data.surahs?.length!==114)throw Error('Meal sürümü doğrulanamadı');let total=0;for(let i=0;i<114;i++){const source=data.surahs[i],target=state.corpus?.surahs?.[i];if(!target||source.number!==target.number||source.ayahs?.length!==target.ayahs.length)throw Error(`${i+1}. sure eşleşmedi`);for(let j=0;j<source.ayahs.length;j++){const ayah=source.ayahs[j],base=target.ayahs[j];if(ayah.numberInSurah!==j+1||ayah.number!==base.global||!ayah.text)throw Error(`${i+1}:${j+1} eşleşmedi`);total++}}if(total!==6236)throw Error(`Ayet sayısı ${total}`);return data}
function applyMeal(data,id){for(let i=0;i<114;i++)for(let j=0;j<data.surahs[i].ayahs.length;j++)state.corpus.surahs[i].ayahs[j].tr=data.surahs[i].ayahs[j].text;state.corpus.edition.turkish=id;localStorage.setItem('quran-meal-edition',id);render();const select=$id('v19-surah-select');if(select)select.value=String(state.selected||'');document.querySelector('.meal-source-note')?.replaceChildren(`Ayetlerin altında ${meals[id]} meali gösteriliyor.`);setStatus(`${meals[id]} meali hazır. 6.236 ayet eşleştirildi ve çevrimdışı kullanım için kaydedildi.`)}
async function changeMeal(id){if(changing||!state.corpus)return;changing=true;const select=$id('meal-edition');if(select)select.disabled=true;setStatus(`${meals[id]} meali hazırlanıyor…`);try{let data=await dbGet(`meal-v1-${id}`);if(!data){if(!navigator.onLine)throw Error('Bu meal henüz indirilmedi; ilk kullanım için internet bağlantısı gerekiyor.');data=validateMeal(await fetchEdition(id),id);await dbPut(`meal-v1-${id}`,data)}else validateMeal(data,id);applyMeal(data,id)}catch(error){setStatus(`Meal değiştirilemedi: ${error.message}`);if(select)select.value=state.corpus.edition?.turkish||'tr.yazir'}finally{changing=false;if(select)select.disabled=false}}
function install(){const options=document.querySelector('.quran-setup-options');if(!options||$id('meal-edition'))return false;const label=document.createElement('label');label.className='meal-picker';label.innerHTML='<span>Türkçe meal</span><select id="meal-edition" aria-label="Türkçe meal yazarı"></select><small class="meal-source-note"></small>';const select=label.querySelector('select');for(const [id,name] of Object.entries(meals)){const option=document.createElement('option');option.value=id;option.textContent=name;select.append(option)}const selected=localStorage.getItem('quran-meal-edition')||state.corpus?.edition?.turkish||'tr.yazir';select.value=selected;label.querySelector('small').textContent=`Ayetlerin altında ${meals[selected]} meali gösteriliyor.`;options.prepend(label);select.onchange=()=>changeMeal(select.value);if(selected!=='tr.yazir')changeMeal(selected);const source=document.querySelector('#source-dialog .dialog-inner');if(source&&!source.querySelector('.meal-sources')){const p=document.createElement('p');p.className='meal-sources';p.innerHTML='<strong>Seçilebilir mealler:</strong> Elmalılı Hamdi Yazır, Süleyman Ateş, Ali Bulaç ve Suat Yıldırım. Metinler AlQuran Cloud sürümlerinden alınır; sure ve ayet numaraları uygulamada yeniden doğrulanır.';source.querySelector('.dialog-head')?.after(p)}const footer=document.querySelector('footer span');if(footer)footer.innerHTML='Kur’an ve mealler: <a href="https://alquran.cloud/">AlQuran Cloud</a> · Seçilen meal cihazda saklanır';return true}
const wait=setInterval(()=>{if(state.corpus&&install())clearInterval(wait)},150);setTimeout(()=>clearInterval(wait),20000);
})();
